Input: N (sites), T (epochs), p in [0,1], L >= 1 (lifetime in epochs)
Output: upper bound on P(two civilizations are ever mutually detectable)

function PAIR-CONTACT-BOUND(T, p, L):
    # exact two-site law is (p/T)^2 per epoch pair;
    # at most T(2L-1) of the T^2 ordered epoch pairs are window-compatible
    return (2L - 1) * p^2 / T

function CONTACT-BOUND(N, T, p, L):
    orderedSitePairs <- N^2 - N
    return orderedSitePairs * PAIR-CONTACT-BOUND(T, p, L)

function COUNT-WINDOW-PAIRS(T, L):        # exact reference count, O(T)
    total <- 0
    for a <- 0 to T-1 do
        lo <- max(0, a - L + 1); hi <- min(T-1, a + L - 1)
        total <- total + (hi - lo + 1)
    assert total <= T * (2L - 1)
    return total

function LEVER-COMPARISON(N, T, p, L):
    base <- CONTACT-BOUND(N, T, p, L)
    return ( CONTACT-BOUND(N, T, 2p, L) / base,     # ~ 4  (quadratic in p)
             CONTACT-BOUND(N, T, p, 2L) / base )    # ~ 3  (linear in L)
